import type { FilterValue } from 'models/Filters';

import type {
  MonthRange,
  YearMonth,
  YearMonthParts,
} from './timePeriodCalendar';
import {
  HALF_MONTH_RANGES,
  HalfKey,
  isHalfKey,
  isQuarterKey,
  isYearMonth,
  MONTH_NAMES_SHORT,
  parseCutoffDate,
  parseYearMonth,
  QUARTER_MONTH_RANGES,
  QuarterKey,
  shiftYearMonth,
  toYearMonth,
} from './timePeriodCalendar';
import { isTimePeriodType, TimePeriodType } from './timePeriodConfig';

export type TimePeriodEnd = YearMonth | QuarterKey | HalfKey | null;
export type MonthStartDate = `${YearMonth}-01`;

export interface DerivedTimePeriodSelection {
  periodType: TimePeriodType;
  dtEnd: MonthStartDate;
  description: string;
  end: TimePeriodEnd;
}

const MIN_CLOSED_MONTH_INDEX: Record<TimePeriodType, number> = {
  [TimePeriodType.YTD]: 0,
  [TimePeriodType.HALF]: HALF_MONTH_RANGES[HalfKey.H1].endMonthIndex,
  [TimePeriodType.QTR]: QUARTER_MONTH_RANGES[QuarterKey.Q1].endMonthIndex,
  [TimePeriodType.R3M]: 0,
  [TimePeriodType.MTH]: 0,
  [TimePeriodType.FY]: 0,
};

const isFixedPeriodType = (type: TimePeriodType): boolean =>
  type === TimePeriodType.HALF || type === TimePeriodType.QTR;

const getFixedPeriodRange = (
  type: TimePeriodType,
  end: TimePeriodEnd,
): MonthRange | null => {
  if (type === TimePeriodType.HALF && isHalfKey(end)) {
    return HALF_MONTH_RANGES[end];
  }
  if (type === TimePeriodType.QTR && isQuarterKey(end)) {
    return QUARTER_MONTH_RANGES[end];
  }
  return null;
};

const getFixedPeriodEnds = (
  type: TimePeriodType,
): ReadonlyArray<HalfKey | QuarterKey> => {
  if (type === TimePeriodType.HALF) return Object.values(HalfKey);
  if (type === TimePeriodType.QTR) return Object.values(QuarterKey);
  return [];
};

const getFixedPeriodEndByMonth = (
  type: TimePeriodType,
  endMonthIndex: number,
): HalfKey | QuarterKey | null => {
  return (
    getFixedPeriodEnds(type).find(
      (end) => getFixedPeriodRange(type, end)?.endMonthIndex === endMonthIndex,
    ) ?? null
  );
};

export function normalizeTimePeriodType(
  type: FilterValue | undefined,
): TimePeriodType | '' {
  const normalized = String(type ?? '')
    .trim()
    .toUpperCase();
  return isTimePeriodType(normalized) ? normalized : '';
}

export function getClosedMonthIndex(cutoffDate: string): number {
  return (parseCutoffDate(cutoffDate)?.month ?? 0) - 1;
}

export function getClosedYear(cutoffDate: string): number {
  return parseCutoffDate(cutoffDate)?.year ?? 0;
}

export function normalizeTimePeriodDtEnd(
  value: string | null | undefined,
): MonthStartDate | null {
  const parsed = parseCutoffDate(value);
  if (!parsed) return null;
  return `${toYearMonth(parsed.month - 1, parsed.year)}-01`;
}

const parseCanonicalMonthStartDate = (
  value: unknown,
): YearMonthParts | null => {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-01$/.test(value)) {
    return null;
  }
  return parseCutoffDate(value);
};

export function isCanonicalMonthStartDate(
  value: unknown,
): value is MonthStartDate {
  return parseCanonicalMonthStartDate(value) !== null;
}

export function hasTimePeriodSelection(
  periodType: FilterValue | undefined,
  dtEnd: FilterValue | undefined,
): boolean {
  return Boolean(
    normalizeTimePeriodType(periodType) && isCanonicalMonthStartDate(dtEnd),
  );
}

export function isMonthAvailable(
  monthIndex: number,
  cutoffDate: string,
): boolean {
  const cutoff = parseCutoffDate(cutoffDate);
  return Boolean(cutoff && monthIndex >= 0 && monthIndex < cutoff.month);
}

export function isQuarterAvailable(
  quarter: QuarterKey,
  cutoffDate: string,
): boolean {
  const closedMonth = getClosedMonthIndex(cutoffDate);
  return closedMonth >= QUARTER_MONTH_RANGES[quarter].endMonthIndex;
}

export function getAvailableQuarters(cutoffDate: string): QuarterKey[] {
  return Object.values(QuarterKey).filter((quarter) =>
    isQuarterAvailable(quarter, cutoffDate),
  );
}

export function isHalfAvailable(half: HalfKey, cutoffDate: string): boolean {
  const closedMonth = getClosedMonthIndex(cutoffDate);
  return closedMonth >= HALF_MONTH_RANGES[half].endMonthIndex;
}

export function getAvailableHalves(cutoffDate: string): HalfKey[] {
  return Object.values(HalfKey).filter((half) =>
    isHalfAvailable(half, cutoffDate),
  );
}

const getLatestClosedYearFromCutoff = ({
  year,
  month,
}: YearMonthParts): number => (month === 12 ? year : year - 1);

export function getDefaultTimePeriodEnd(
  type: string | null | undefined,
  cutoffDate: string | null | undefined,
): TimePeriodEnd {
  const normalizedType = normalizeTimePeriodType(type);
  const cutoff = parseCutoffDate(cutoffDate);
  if (!normalizedType || !cutoff || !cutoffDate) return null;

  if (
    normalizedType === TimePeriodType.YTD ||
    normalizedType === TimePeriodType.R3M ||
    normalizedType === TimePeriodType.MTH
  ) {
    return toYearMonth(cutoff.month - 1, cutoff.year);
  }
  if (normalizedType === TimePeriodType.QTR) {
    const quarters = getAvailableQuarters(cutoffDate);
    return quarters[quarters.length - 1] ?? null;
  }
  if (normalizedType === TimePeriodType.HALF) {
    const halves = getAvailableHalves(cutoffDate);
    return halves[halves.length - 1] ?? null;
  }
  return null;
}

export function isPeriodTypeEnabled(type: string, cutoffDate: string): boolean {
  const normalizedType = normalizeTimePeriodType(type);
  const closedMonth = getClosedMonthIndex(cutoffDate);
  if (!normalizedType || closedMonth < 0) return false;
  return closedMonth >= MIN_CLOSED_MONTH_INDEX[normalizedType];
}

const getTimePeriodDtEndForCutoff = (
  type: TimePeriodType,
  end: TimePeriodEnd,
  cutoff: YearMonthParts,
): MonthStartDate | null => {
  if (type === TimePeriodType.FY) {
    return `${toYearMonth(11, getLatestClosedYearFromCutoff(cutoff))}-01`;
  }
  if (isFixedPeriodType(type)) {
    const range = getFixedPeriodRange(type, end);
    return range ? `${toYearMonth(range.endMonthIndex, cutoff.year)}-01` : null;
  }
  if (!isYearMonth(end)) return null;
  return `${end}-01`;
};

export function parseDtEndToTimePeriodEnd(
  type: string,
  dtEnd: string | null | undefined,
): TimePeriodEnd {
  const normalizedType = normalizeTimePeriodType(type);
  const parsed = parseCanonicalMonthStartDate(dtEnd);
  if (!normalizedType || !parsed) return null;
  if (normalizedType === TimePeriodType.FY) return null;
  if (isFixedPeriodType(normalizedType)) {
    return getFixedPeriodEndByMonth(normalizedType, parsed.month - 1);
  }
  return toYearMonth(parsed.month - 1, parsed.year);
}

const isEndAvailable = (
  type: TimePeriodType,
  end: TimePeriodEnd,
  cutoff: YearMonthParts,
): boolean => {
  const closedMonthIndex = cutoff.month - 1;
  if (closedMonthIndex < MIN_CLOSED_MONTH_INDEX[type]) return false;
  if (type === TimePeriodType.FY) return end === null;
  if (isFixedPeriodType(type)) {
    const range = getFixedPeriodRange(type, end);
    return Boolean(range && closedMonthIndex >= range.endMonthIndex);
  }
  if (!isYearMonth(end)) return false;
  const parsed = parseYearMonth(end);
  if (parsed?.year !== cutoff.year || parsed.month > cutoff.month) {
    return false;
  }
  return true;
};

const formatFixedRange = (
  { startMonthIndex, endMonthIndex }: MonthRange,
  year: number,
): string =>
  `${MONTH_NAMES_SHORT[startMonthIndex]} - ${MONTH_NAMES_SHORT[endMonthIndex]}, ${year}`;

const formatTimePeriodRange = (
  type: TimePeriodType,
  end: TimePeriodEnd,
  cutoff: YearMonthParts,
): string => {
  if (type === TimePeriodType.FY) {
    return `Jan - Dec, ${getLatestClosedYearFromCutoff(cutoff)}`;
  }
  if (isFixedPeriodType(type)) {
    const range = getFixedPeriodRange(type, end);
    return range ? formatFixedRange(range, cutoff.year) : '';
  }
  if (!isYearMonth(end)) return '';
  const parsed = parseYearMonth(end);
  if (!parsed) return '';
  const endMonth = MONTH_NAMES_SHORT[parsed.month - 1];
  if (type === TimePeriodType.YTD) {
    return `Jan - ${endMonth}, ${parsed.year}`;
  }
  if (type === TimePeriodType.MTH) return `${endMonth}, ${parsed.year}`;
  const start = shiftYearMonth(parsed.year, parsed.month, -2);
  if (start.year !== parsed.year) {
    return `${MONTH_NAMES_SHORT[start.month - 1]}, ${start.year} - ${endMonth}, ${parsed.year}`;
  }
  return `${MONTH_NAMES_SHORT[start.month - 1]} - ${endMonth}, ${parsed.year}`;
};

export function deriveTimePeriodSelection(
  type: TimePeriodType | '' | null | undefined,
  end: TimePeriodEnd,
  cutoffDate: string | null | undefined,
): DerivedTimePeriodSelection | null {
  const periodType = normalizeTimePeriodType(type);
  const cutoff = parseCutoffDate(cutoffDate);
  if (!periodType || !cutoff) return null;

  if (!isEndAvailable(periodType, end, cutoff)) return null;
  const dtEnd = getTimePeriodDtEndForCutoff(periodType, end, cutoff);
  if (!dtEnd) return null;
  return {
    periodType,
    dtEnd,
    description: formatTimePeriodRange(periodType, end, cutoff),
    end,
  };
}

export function isTimePeriodSelectionAvailable(
  periodType: FilterValue | undefined,
  dtEnd: FilterValue | undefined,
  cutoffDate: string | null | undefined,
): boolean {
  return Boolean(resolveTimePeriodSelection(periodType, dtEnd, cutoffDate));
}

export function resolveTimePeriodSelection(
  periodType: FilterValue | undefined,
  dtEnd: FilterValue | undefined,
  cutoffDate: string | null | undefined,
): DerivedTimePeriodSelection | null {
  if (!isCanonicalMonthStartDate(dtEnd) || !cutoffDate) return null;
  const normalizedType = normalizeTimePeriodType(periodType);
  if (!normalizedType) return null;
  const end = parseDtEndToTimePeriodEnd(normalizedType, dtEnd);
  const selection = deriveTimePeriodSelection(normalizedType, end, cutoffDate);
  return selection?.dtEnd === dtEnd ? selection : null;
}

export function formatTimePeriodLabel(
  type: string,
  end: TimePeriodEnd,
  year?: number,
): string {
  const normalizedType = normalizeTimePeriodType(type);
  if (!normalizedType) return '';
  const yearShort = year ? String(year).slice(2) : '';
  if (normalizedType === TimePeriodType.HALF) {
    return end ? `Half ${end}'${yearShort}` : 'Half';
  }
  if (normalizedType === TimePeriodType.QTR) {
    return end ? `QTR ${end}'${yearShort}` : 'QTR';
  }
  if (normalizedType === TimePeriodType.FY) {
    return year ? `FY'${yearShort}` : 'FY';
  }
  if (typeof end !== 'string') return normalizedType;
  const parsed = parseYearMonth(end);
  if (!parsed) return normalizedType;
  return `${normalizedType} ${MONTH_NAMES_SHORT[parsed.month - 1]}'${String(
    parsed.year,
  ).slice(2)}`;
}

export {
  HalfKey,
  HALF_MONTH_RANGES,
  isHalfKey,
  isQuarterKey,
  isYearMonth,
  MONTH_NAMES_SHORT,
  QuarterKey,
  QUARTER_MONTH_RANGES,
  toYearMonth,
} from './timePeriodCalendar';
export type { YearMonth } from './timePeriodCalendar';
export { TimePeriodType } from './timePeriodConfig';
